"""OBSOLETE (7 Oct 2026): Experiment 3 (text generated by Claude Haiku 4.5) was removed from the paper; kept for the record, not run by run_all.sh.
Experiment 3, prognostic views on the 500-post model-X subsample (Section 4.3 / Appendix D).

On the n' = 500 posts of the CRT subsample (direction w fitted on the other 2500 rows, as in exp3_diagnostics.py):
  (1) a regression-free estimate of Var(E[A|Z]) from the 19 regenerated comments, Cov(A, A'^{(b)}) averaged over b
      (A and A' are conditionally i.i.d. given Z; the persona is redrawn per regeneration), hence the identified R2_A(E1);
  (2) the insufficiency of E1 demonstrated by three views: E2(Z); a supervised one-dimensional prognostic view, the ridge
      prediction of A (of B) from [E1,E2](Z) trained on the 2500 other posts; and the Monte-Carlo prognostic view for A,
      the mean sentiment of the 19 regenerated comments (MSE-difference estimator as in the paper, and the squared
      out-of-fold correlation of Section 3.4);
  (3) rho_hat, se and RV_alpha for five conditioning sets: E1; [E1, mc_A]; [E1, sup_A, sup_B]; [sup_A, sup_B]; [mc_A, sup_B].
Reads only cached embeddings and the existing generations; no API calls.  Output: results/exp3_prognostic.json and the
macro lines for results_macros.tex (printed).  Usage: python experiments/exp3_prognostic.py
"""
from __future__ import annotations

import json
import sys
from pathlib import Path

import numpy as np
from sklearn.linear_model import RidgeCV
from threadpoolctl import threadpool_limits

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from citext.estimators import crossfit_folds, fit_predict_crossfit, gcm_from_residuals  # noqa: E402
from citext.paths import RESULTS_DIR  # noqa: E402
from citext.text_semi import E1_NAME, E2_NAME, embed_texts  # noqa: E402

LLM = Path.home() / ".cache/ci_text/llm"
GEN = LLM / "gen_claude-haiku-4-5_n3000.jsonl"
CRT = LLM / "crt_claude-haiku-4-5_n500_B19.jsonl"
LABEL_SCORE = {"POSITIVE": 1.0, "NEUTRAL": 0.0, "NEGATIVE": -1.0}
K, SEED, PRIMARY = 5, 0, "ridge"   # ridge throughout in Experiment 3 (30 Sept 2026), as in exp3_llm.py


def main():
    rows = [json.loads(l) for l in GEN.read_text().splitlines() if l.strip()]
    rows = [r for r in rows if r["X"] and r["Y0"] and r["Y1"]]
    rows.sort(key=lambda r: r["idx"])
    n = len(rows)
    idx_all = np.array([r["idx"] for r in rows])
    Z, X, Y0 = [r["Z"] for r in rows], [r["X"] for r in rows], [r["Y0"] for r in rows]
    s = np.array([LABEL_SCORE.get(r["X_label"], 0.0) for r in rows])
    E1Z, E1X, E1Y0 = embed_texts(Z, E1_NAME, "diagZ"), embed_texts(X, E1_NAME, "diagX"), embed_texts(Y0, E1_NAME, "diagY0")
    E2Z = embed_texts(Z, E2_NAME, "diagZ")
    crt = [json.loads(l) for l in CRT.read_text().splitlines() if l.strip()]
    draws: dict = {}
    for r in crt:
        draws.setdefault(r["idx"], {})[r["b"]] = r["X_prime"]
    Bd = 19
    sub_idx = sorted(i for i, d in draws.items() if len(d) >= Bd)
    pos = {ix: k for k, ix in enumerate(idx_all)}
    sub = np.array([pos[i] for i in sub_idx])
    rest = np.setdiff1d(np.arange(n), sub)
    m = len(sub)
    alphas = np.logspace(-2, 4, 13)
    w = RidgeCV(alphas=alphas).fit(E1X[rest], s[rest])                       # direction fitted outside the subsample
    A, B, Psi = w.predict(E1X[sub]), w.predict(E1Y0[sub]), E1Z[sub]
    texts_b = [draws[i][b] for b in range(Bd) for i in sub_idx]
    Eb = embed_texts(texts_b, E1_NAME, f"diagXprime_{m}x{Bd}").reshape(Bd, m, -1)
    Ap = np.stack([w.predict(Eb[b]) for b in range(Bd)])                     # (19, m) sentiment of regenerated comments
    mcA = Ap.mean(0)
    ZZ = np.hstack([E1Z, E2Z])
    supA = RidgeCV(alphas=alphas).fit(ZZ[rest], w.predict(E1X[rest])).predict(ZZ[sub])
    supB = RidgeCV(alphas=alphas).fit(ZZ[rest], w.predict(E1Y0[rest])).predict(ZZ[sub])
    folds = crossfit_folds(m, K, SEED)
    col = lambda v: v[:, None]  # noqa: E731

    covs = np.array([np.cov(A, Ap[b])[0, 1] for b in range(Bd)])
    out = {"n_sub": int(m), "B": Bd, "var_A": float(A.var()), "var_EA_given_Z": float(covs.mean()),
           "total_R2_A_on_Z": float(covs.mean() / A.var()), "corr_A_mcA": float(np.corrcoef(A, mcA)[0, 1]),
           "corr_B_supB": float(np.corrcoef(B, supB)[0, 1]), "reliability_mcA": float(covs.mean() / (covs.mean() + (A.var() - covs.mean()) / Bd))}

    def fit(Xm, y, reg):
        return fit_predict_crossfit(Xm, y, K, SEED, reg, folds)

    def bench(y, P0, P1, reg):
        m0, m1 = fit(P0, y, reg), fit(np.hstack([P0, P1]), y, reg)
        r0, g = y - m0, m1 - m0
        return {"mse_diff": float(max(0.0, (np.mean(r0**2) - np.mean((y - m1)**2)) / np.mean(r0**2))),
                "corr2": float(np.corrcoef(r0, g)[0, 1] ** 2)}

    def test(P, reg):
        r = gcm_from_residuals(A - fit(P, A, reg), B - fit(P, B, reg))
        return {"rho": float(r.rho_hat), "se": float(r.se), "RV_alpha": float(r.RV_alpha), "p": float(r.pvalue)}

    with threadpool_limits(4):
        for reg in (PRIMARY, "krr"):
            o = {}
            mseA = float(np.mean((A - fit(Psi, A, reg)) ** 2))
            o["R2_A_on_E1"] = float(1 - mseA / A.var())
            o["R2_B_on_E1"] = float(1 - np.mean((B - fit(Psi, B, reg)) ** 2) / B.var())
            o["identified_R2_A_E1"] = float((covs.mean() - (A.var() - mseA)) / mseA)
            o["bench_A"] = {"E2": bench(A, Psi, E2Z[sub], reg), "sup": bench(A, Psi, col(supA), reg), "mc": bench(A, Psi, col(mcA), reg)}
            o["bench_B"] = {"E2": bench(B, Psi, E2Z[sub], reg), "sup": bench(B, Psi, col(supB), reg)}
            o["rho_bench_sup"] = float(np.sqrt(o["bench_A"]["sup"]["mse_diff"] * o["bench_B"]["sup"]["mse_diff"]))
            o["rho_bench_E2"] = float(np.sqrt(o["bench_A"]["E2"]["mse_diff"] * o["bench_B"]["E2"]["mse_diff"]))
            o["tests"] = {"E1": test(Psi, reg), "E1+mcA": test(np.hstack([Psi, col(mcA)]), reg),
                          "E1+supA+supB": test(np.hstack([Psi, col(supA), col(supB)]), reg),
                          "supA+supB": test(np.hstack([col(supA), col(supB)]), reg),
                          "mcA+supB": test(np.hstack([col(mcA), col(supB)]), reg)}
            out[reg] = o
            print(f"[{reg}] R2(A|E1)={o['R2_A_on_E1']:.3f} R2(B|E1)={o['R2_B_on_E1']:.3f} identified R2_A(E1)={o['identified_R2_A_E1']:.3f}")
            for side in ("bench_A", "bench_B"):
                print(f"  {side}: " + "; ".join(f"{k}: mse {v['mse_diff']:.3f} / corr2 {v['corr2']:.3f}" for k, v in o[side].items()))
            for k, v in o["tests"].items():
                print(f"  rho({k:13s}) = {v['rho']:.3f} (se {v['se']:.3f}), RV_alpha {v['RV_alpha']:.3f}, p {v['p']:.2g}")
    (RESULTS_DIR / "exp3_prognostic.json").write_text(json.dumps(out, indent=1))
    p = out[PRIMARY]
    t = p["tests"]
    other = [k for k in out if isinstance(out.get(k), dict) and "tests" in out[k] and k != PRIMARY]
    maxdiff = 0.0
    for k in other:   # largest change of any reported entry when the secondary regressor replaces the primary
        q = out[k]
        maxdiff = max([maxdiff] + [abs(q["tests"][s]["rho"] - t[s]["rho"]) for s in t] +
                      [abs(q["bench_A"][v]["mse_diff"] - p["bench_A"][v]["mse_diff"]) for v in p["bench_A"]] +
                      [abs(q["bench_B"][v]["mse_diff"] - p["bench_B"][v]["mse_diff"]) for v in p["bench_B"]])
    macros = [
        r"\newcommand{\resProgMaxDiffKRR}{%.2f}" % maxdiff,
        "%% ---------- Experiment 3, prognostic views (written by exp3_prognostic.py, primary regressor %s) ----------" % PRIMARY,
        r"\newcommand{\resProgN}{%d}" % out["n_sub"],
        r"\newcommand{\resProgTotalRtwoA}{%.2f}" % out["total_R2_A_on_Z"],
        r"\newcommand{\resProgRtwoAEone}{%.2f}" % p["R2_A_on_E1"],
        r"\newcommand{\resProgIdentRtwoA}{%.2f}" % p["identified_R2_A_E1"],
        r"\newcommand{\resProgBenchAEtwo}{%.3f}" % p["bench_A"]["E2"]["mse_diff"],
        r"\newcommand{\resProgBenchASup}{%.3f}" % p["bench_A"]["sup"]["mse_diff"],
        r"\newcommand{\resProgBenchAMc}{%.3f}" % p["bench_A"]["mc"]["mse_diff"],
        r"\newcommand{\resProgBenchBEtwo}{%.3f}" % p["bench_B"]["E2"]["mse_diff"],
        r"\newcommand{\resProgBenchBSup}{%.3f}" % p["bench_B"]["sup"]["mse_diff"],
        r"\newcommand{\resProgCorrAEtwo}{%.3f}" % p["bench_A"]["E2"]["corr2"],
        r"\newcommand{\resProgCorrASup}{%.3f}" % p["bench_A"]["sup"]["corr2"],
        r"\newcommand{\resProgCorrAMc}{%.3f}" % p["bench_A"]["mc"]["corr2"],
        r"\newcommand{\resProgCorrBEtwo}{%.3f}" % p["bench_B"]["E2"]["corr2"],
        r"\newcommand{\resProgCorrBSup}{%.3f}" % p["bench_B"]["sup"]["corr2"],
        r"\newcommand{\resProgBenchSup}{%.3f}" % p["rho_bench_sup"],
        r"\newcommand{\resProgBenchEtwo}{%.3f}" % p["rho_bench_E2"],
        r"\newcommand{\resProgRhoEone}{%.3f}" % t["E1"]["rho"], r"\newcommand{\resProgSeEone}{%.3f}" % t["E1"]["se"],
        r"\newcommand{\resProgRValphaEone}{%.2f}" % t["E1"]["RV_alpha"],
        r"\newcommand{\resProgRhoEoneMc}{%.3f}" % t["E1+mcA"]["rho"],
        r"\newcommand{\resProgRhoEoneSup}{%.3f}" % t["E1+supA+supB"]["rho"],
        r"\newcommand{\resProgRhoSup}{%.3f}" % t["supA+supB"]["rho"], r"\newcommand{\resProgSeSup}{%.3f}" % t["supA+supB"]["se"],
        r"\newcommand{\resProgRhoMcSup}{%.3f}" % t["mcA+supB"]["rho"], r"\newcommand{\resProgSeMcSup}{%.3f}" % t["mcA+supB"]["se"],
        r"\newcommand{\resProgPMcSup}{%.2f}" % t["mcA+supB"]["p"],
        r"\newcommand{\resProgSeEoneMc}{%.3f}" % t["E1+mcA"]["se"], r"\newcommand{\resProgRValphaEoneMc}{%.2f}" % t["E1+mcA"]["RV_alpha"],
        r"\newcommand{\resProgSeEoneSup}{%.3f}" % t["E1+supA+supB"]["se"], r"\newcommand{\resProgRValphaEoneSup}{%.2f}" % t["E1+supA+supB"]["RV_alpha"],
        r"\newcommand{\resProgRValphaSup}{%.2f}" % t["supA+supB"]["RV_alpha"],
        r"\newcommand{\resProgRValphaMcSup}{%.2f}" % t["mcA+supB"]["RV_alpha"],
        r"\newcommand{\resProgReliabilityMc}{%.2f}" % out["reliability_mcA"],
    ]
    print("\n".join(macros))
    (RESULTS_DIR / "exp3_prognostic_macros.tex").write_text("\n".join(macros) + "\n")


if __name__ == "__main__":
    main()
